#!/bin/sh
# Fetch the pinned E2 inputs into ./inputs and check every SHA-256. POSIX sh; needs curl and sha256sum.
set -eu
mkdir -p inputs
fetch() {
  mkdir -p "inputs/$(dirname "$1")"
  curl -fsSL -o "inputs/$1" "$2"
  echo "$3  inputs/$1" | sha256sum -c --quiet -
}
